class Solution { public int makeConnected(int n,int[][] connections){if(connections.length<n-1)return -1;int[] parent=new int[n];for(int i=0;i<n;i++)parent[i]=i;for(int[] edge:connections){int a=find(parent,edge[0]),b=find(parent,edge[1]);if(a!=b)parent[b]=a;}int components=0;for(int i=0;i<n;i++)if(find(parent,i)==i)components++;return components-1;}private int find(int[] parent,int node){if(parent[node]!=node)parent[node]=find(parent,parent[node]);return parent[node];} }
